def find_golomb_ruler(n, max_len=None):
    """Find a Golomb ruler with n marks using backtracking."""
    if max_len is None:
        # Upper bound: use known bounds
        # For n=10, optimal is 72
        max_len = 80

    ruler = [0]
    diffs = set()

    def backtrack(last_pos):
        if len(ruler) == n:
            return True

        for pos in range(last_pos + 1, max_len + 1):
            # Check if all differences with existing marks are unique
            new_diffs = []
            valid = True
            for mark in ruler:
                d = pos - mark
                if d in diffs:
                    valid = False
                    break
                new_diffs.append(d)

            if valid:
                # Add position
                ruler.append(pos)
                for d in new_diffs:
                    diffs.add(d)

                if backtrack(pos):
                    return True

                # Remove position
                ruler.pop()
                for d in new_diffs:
                    diffs.remove(d)

        return False

    if backtrack(0):
        return ruler
    return None

